// Deterministic SWR simulation over a logical clock.
// cache.freshUntil = 60; recompute takes 3 logical ticks and yields 'v2'.
const cache = { value: 'v1', freshUntil: 60, refreshInFlight: false, refreshStartedAt: null };
let backgroundRefreshes = 0;
const RECOMPUTE_TICKS = 3;
const FRESH_VALUE = 'v2';

function settleRefresh(now) {
  // If a refresh has been in flight long enough, land the fresh value.
  if (cache.refreshInFlight && now - cache.refreshStartedAt >= RECOMPUTE_TICKS) {
    cache.value = FRESH_VALUE;
    cache.freshUntil = now + 60;
    cache.refreshInFlight = false;
    cache.refreshStartedAt = null;
  }
}

function handle(now) {
  settleRefresh(now);
  const isStale = now >= cache.freshUntil;
  if (isStale && !cache.refreshInFlight) {
    // FIRST request past the deadline: serve stale AND kick off ONE background refresh.
    cache.refreshInFlight = true;
    cache.refreshStartedAt = now;
    backgroundRefreshes++;
  }
  // All requests (including the trigger) get whatever value is current — never block.
  return cache.value;
}

// Replay 6 requests at logical times 60..65.
const served = [];
for (let now = 60; now <= 65; now++) {
  served.push(handle(now));
}
console.log('served=' + served.join(','));
console.log('backgroundRefreshes=' + backgroundRefreshes);
